FILES = {
  "server/services/qikink.py": "\"\"\"Qikink Sandbox only. No storefront hooks, wallet calls, or automatic order retries.\"\"\"\nfrom __future__ import annotations\n\nimport asyncio\nimport hashlib\nimport json\nimport os\nimport sqlite3\nimport time\nfrom contextlib import closing\nfrom pathlib import Path\nfrom typing import Literal\n\nimport httpx\nfrom pydantic import BaseModel, ConfigDict, Field, field_validator\n\nSANDBOX_BASE = \"https://sandbox.qikink.com\"\nDEFAULT_JOURNAL = Path(__file__).resolve().parents[1] / \"data\" / \"qikink_sandbox.db\"\n\n\nclass QikinkError(RuntimeError):\n    \"\"\"Safe to display: never contains response bodies, tokens, or request data.\"\"\"\n\n\nclass DuplicateBlocked(QikinkError):\n    pass\n\n\nclass OutcomeUnknown(QikinkError):\n    pass\n\n\nclass ShippingAddress(BaseModel):\n    model_config = ConfigDict(extra=\"forbid\", str_strip_whitespace=True)\n    first_name: str = Field(min_length=1, max_length=20)\n    last_name: str = Field(default=\"\", max_length=20)\n    address1: str = Field(min_length=1, max_length=90)\n    address2: str = Field(default=\"\", max_length=90)\n    phone: str = Field(min_length=1, max_length=15)\n    email: str = Field(min_length=1, max_length=254)\n    city: str = Field(min_length=1, max_length=40)\n    zip: str = Field(pattern=r\"^[0-9]{6}$\")\n    province: str = Field(min_length=1, max_length=40)\n    # Only the India plain-product flow has been tested so far.\n    country_code: Literal[\"IN\"] = \"IN\"\n\n\nclass PlainOrder(BaseModel):\n    model_config = ConfigDict(extra=\"forbid\", str_strip_whitespace=True)\n    reference: str = Field(pattern=r\"^[a-z0-9_]{1,15}$\")\n    sku: str = Field(min_length=1, max_length=50)\n    quantity: int = Field(default=1, ge=1, le=100, strict=True)\n    price: str = \"1\"\n    total_order_value: str = \"1\"\n    shipping_address: ShippingAddress\n\n    @field_validator(\"price\", \"total_order_value\")\n    @classmethod\n    def numeric_amount(cls, value: str) -> str:\n        from decimal import Decimal, InvalidOperation\n        try:\n            amount = Decimal(value)\n        except InvalidOperation:\n            raise ValueError(\"Amount must be numeric\") from None\n        if not amount.is_finite() or amount < 0:\n            raise ValueError(\"Amount must be finite and non-negative\")\n        return format(amount, \"f\")\n\n    def payload(self) -> dict:\n        address = self.shipping_address.model_dump(exclude_defaults=True)\n        address[\"country_code\"] = self.shipping_address.country_code\n        return {\n            \"order_number\": self.reference,\n            \"qikink_shipping\": \"1\",\n            \"gateway\": \"Prepaid\",\n            \"total_order_value\": self.total_order_value,\n            \"line_items\": [{\n                \"search_from_my_products\": 0,\n                \"print_type_id\": \"1\",\n                \"quantity\": str(self.quantity),\n                \"price\": self.price,\n                \"sku\": self.sku,\n            }],\n            \"shipping_address\": address,\n        }\n\n\ndef _digest(value: dict) -> str:\n    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(\",\", \":\")).encode()).hexdigest()\n\n\ndef _order_id(value) -> str | None:\n    if isinstance(value, bool) or not isinstance(value, (str, int)):\n        return None\n    text = str(value)\n    return text if text.isascii() and text.isdigit() and int(text) > 0 else None\n\n\nclass SandboxJournal:\n    \"\"\"Separate SQLite journal. Stores hashes, references and IDs, never addresses/tokens.\n\n    pending/uncertain records must be reconciled manually; they are never retried.\n    Atomic reservations protect multiple processes sharing this same database.\n    \"\"\"\n\n    def __init__(self, path: Path = DEFAULT_JOURNAL):\n        self.path = Path(path)\n        self.path.parent.mkdir(parents=True, exist_ok=True)\n        with closing(self._connect()) as db, db:\n            db.execute(\"\"\"CREATE TABLE IF NOT EXISTS qikink_orders (\n                account TEXT NOT NULL, reference TEXT NOT NULL, payload_hash TEXT NOT NULL,\n                state TEXT NOT NULL, order_id TEXT, updated_at REAL NOT NULL,\n                PRIMARY KEY (account, reference))\"\"\")\n\n    def _connect(self):\n        return sqlite3.connect(self.path, timeout=10)\n\n    def reserve(self, account: str, order: PlainOrder, known_id: str | None = None) -> dict:\n        fingerprint = _digest(order.payload())\n        with closing(self._connect()) as db, db:\n            db.execute(\"BEGIN IMMEDIATE\")\n            row = db.execute(\n                \"SELECT payload_hash, state, order_id FROM qikink_orders WHERE account=? AND reference=?\",\n                (account, order.reference),\n            ).fetchone()\n            if row:\n                if row[0] != fingerprint:\n                    raise DuplicateBlocked(\"Reference already registered with a different payload\")\n                if row[1] == \"created\":\n                    if known_id is not None and known_id != row[2]:\n                        raise DuplicateBlocked(\"Reference already linked to a different order ID\")\n                    return {\"state\": \"created\", \"order_id\": row[2], \"cached\": True}\n                if known_id is not None:\n                    raise DuplicateBlocked(\"Existing reservation requires manual reconciliation\")\n                if row[1] != \"not_sent\":\n                    raise DuplicateBlocked(\"Reference blocked; inspect the journal before any resubmission\")\n                db.execute(\"UPDATE qikink_orders SET state='pending', updated_at=? WHERE account=? AND reference=?\",\n                           (time.time(), account, order.reference))\n            else:\n                db.execute(\"INSERT INTO qikink_orders VALUES (?, ?, ?, ?, ?, ?)\",\n                           (account, order.reference, fingerprint,\n                            \"created\" if known_id else \"pending\", known_id, time.time()))\n        return {\"state\": \"created\" if known_id else \"pending\", \"order_id\": known_id, \"cached\": False}\n\n    def finish(self, account: str, reference: str, state: str, order_id: str | None = None):\n        with closing(self._connect()) as db, db:\n            db.execute(\"UPDATE qikink_orders SET state=?, order_id=?, updated_at=? WHERE account=? AND reference=?\",\n                       (state, order_id, time.time(), account, reference))\n\n    def get(self, account: str, reference: str) -> dict | None:\n        with closing(self._connect()) as db:\n            row = db.execute(\"SELECT state, order_id FROM qikink_orders WHERE account=? AND reference=?\",\n                             (account, reference)).fetchone()\n        return {\"reference\": reference, \"state\": row[0], \"order_id\": row[1]} if row else None\n\n\nclass SandboxClient:\n    def __init__(self, client_id: str, client_secret: str, journal: SandboxJournal,\n                 *, transport: httpx.AsyncBaseTransport | None = None):\n        if os.getenv(\"QIKINK_ENV\", \"sandbox\").strip().lower() != \"sandbox\":\n            raise QikinkError(\"Only QIKINK_ENV=sandbox is supported\")\n        if not client_id.strip() or not client_secret.strip():\n            raise QikinkError(\"Missing Qikink Sandbox credentials\")\n        self._client_id = client_id.strip()\n        self._secret = client_secret.strip()\n        self.account = hashlib.sha256(self._client_id.encode()).hexdigest()\n        self.journal = journal\n        self._http = httpx.AsyncClient(timeout=30, follow_redirects=False, transport=transport)\n        self._token = \"\"\n        self._expires = 0.0\n        self._auth_lock = asyncio.Lock()\n\n    @classmethod\n    def from_env(cls, journal: SandboxJournal):\n        return cls(os.getenv(\"QIKINK_SANDBOX_CLIENT_ID\", \"\"),\n                   os.getenv(\"QIKINK_SANDBOX_CLIENT_SECRET\", \"\"), journal)\n\n    async def __aenter__(self):\n        return self\n\n    async def __aexit__(self, *args):\n        await self._http.aclose()\n\n    async def authenticate(self) -> None:\n        async with self._auth_lock:\n            if self._token and self._expires > time.monotonic() + 30:\n                return\n            try:\n                response = await self._http.post(SANDBOX_BASE + \"/api/token\", data={\n                    \"ClientId\": self._client_id, \"client_secret\": self._secret,\n                })\n                if response.status_code != 200:\n                    raise QikinkError(f\"Sandbox authentication failed: HTTP {response.status_code}\")\n                data = response.json()\n                token = data.get(\"Accesstoken\")\n                expires = int(data.get(\"expires_in\", 3600))\n                if not isinstance(token, str) or not token.strip() or expires <= 0:\n                    raise ValueError\n            except (httpx.HTTPError, ValueError, TypeError, AttributeError, OverflowError):\n                raise QikinkError(\"Sandbox authentication unavailable or invalid response\") from None\n            self._token = token\n            self._expires = time.monotonic() + expires\n\n    async def create_plain_order(self, order: PlainOrder) -> dict:\n        # Revalidate/copy so callers cannot change nested fields across awaits.\n        order = PlainOrder.model_validate(order.model_dump())\n        result = self.journal.reserve(self.account, order)\n        if result[\"state\"] == \"created\":\n            return {**result, \"reference\": order.reference}\n        try:\n            await self.authenticate()\n        except BaseException:\n            # No order request has been attempted: retrying this reference is safe.\n            self.journal.finish(self.account, order.reference, \"not_sent\")\n            raise\n        try:\n            response = await self._http.post(\n                SANDBOX_BASE + \"/api/order/create\", json=order.payload(),\n                headers={\"ClientId\": self._client_id, \"Accesstoken\": self._token},\n            )\n            if response.status_code == 400:\n                self.journal.finish(self.account, order.reference, \"rejected\")\n                raise QikinkError(\"Sandbox rejected the order (HTTP 400); no automatic retry\")\n            if response.status_code != 200:\n                raise ValueError\n            data = response.json()\n            remote_id = _order_id(data.get(\"order_id\"))\n            if str(data.get(\"status_code\")) != \"200\" or remote_id is None:\n                raise ValueError\n        except QikinkError:\n            raise\n        except BaseException as exc:\n            self.journal.finish(self.account, order.reference, \"uncertain\")\n            if isinstance(exc, (KeyboardInterrupt, SystemExit, asyncio.CancelledError)):\n                raise\n            raise OutcomeUnknown(\"Sandbox creation result unknown; do not resubmit\") from None\n        # If this commit fails, pending remains blocked. Never resend to recover it.\n        self.journal.finish(self.account, order.reference, \"created\", remote_id)\n        return {\"state\": \"created\", \"order_id\": remote_id, \"reference\": order.reference, \"cached\": False}\n\n    def remember_existing(self, order: PlainOrder, order_id: str) -> dict:\n        remote_id = _order_id(order_id)\n        if remote_id is None:\n            raise QikinkError(\"Invalid existing order ID\")\n        return self.journal.reserve(self.account, order, known_id=remote_id)\n\n    async def lookup(self, order_id: str) -> dict:\n        remote_id = _order_id(order_id)\n        if remote_id is None:\n            raise QikinkError(\"Invalid order ID\")\n        await self.authenticate()\n        attempts = []\n        for path in (\"/api/order/list\", \"/api/order\"):\n            try:\n                response = await self._http.get(SANDBOX_BASE + path,\n                    params={\"id\": remote_id, \"params\": \"order_id,number,status\"},\n                    headers={\"ClientId\": self._client_id, \"Accesstoken\": self._token})\n                attempt = {\"path\": path, \"http_status\": response.status_code}\n                attempts.append(attempt)\n                if response.status_code != 200:\n                    continue\n                data = response.json()\n                # Only documented top-level order or list/data envelope shapes.\n                if isinstance(data, dict) and data.get(\"success\") is False:\n                    continue\n                records = data.get(\"data\", data) if isinstance(data, dict) else data\n                records = [records] if isinstance(records, dict) else records\n                if isinstance(records, list):\n                    for record in records:\n                        if isinstance(record, dict) and _order_id(record.get(\"order_id\")) == remote_id:\n                            return {\"state\": \"found\", \"order_id\": remote_id,\n                                    \"attempts\": attempts}\n            except (httpx.HTTPError, ValueError, TypeError):\n                if not attempts or attempts[-1][\"path\"] != path:\n                    attempts.append({\"path\": path})\n                attempts[-1][\"response_unavailable\"] = True\n        # Read failure never changes a successful creation journal record.\n        return {\"state\": \"unverified\", \"order_id\": remote_id, \"attempts\": attempts}\n",
  "server/scripts/qikink_sandbox.py": "#!/usr/bin/env python3\n\"\"\"Sandbox-only Qikink CLI. Plain orders default to a dry run.\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport asyncio\nimport json\nimport sys\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\nsys.path.insert(0, str(ROOT))\n\nfrom dotenv import load_dotenv\nfrom services.qikink import PlainOrder, QikinkError, SandboxClient, SandboxJournal, DEFAULT_JOURNAL\n\n\n# Matches the synthetic address of the manually confirmed Sandbox order.\nTEST_ADDRESS = {\n    \"first_name\": \"Sandbox\", \"last_name\": \"Test\", \"address1\": \"Sandbox test address\",\n    \"phone\": \"9876543210\", \"email\": \"sandbox@example.com\", \"city\": \"Coimbatore\",\n    \"zip\": \"641001\", \"province\": \"Tamil Nadu\", \"country_code\": \"IN\",\n}\n\n\ndef parser() -> argparse.ArgumentParser:\n    cli = argparse.ArgumentParser(description=__doc__)\n    cli.add_argument(\"--journal\", type=Path, default=DEFAULT_JOURNAL)\n    commands = cli.add_subparsers(dest=\"command\", required=True)\n    commands.add_parser(\"auth\", help=\"Authenticate only; prints no token\")\n    lookup = commands.add_parser(\"lookup\", help=\"Read only; unavailable Sandbox routes are reported\")\n    lookup.add_argument(\"order_id\")\n    history = commands.add_parser(\"status\", help=\"Read the local journal, with no network call\")\n    history.add_argument(\"reference\")\n    for name in (\"plain\", \"remember\"):\n        sub = commands.add_parser(name)\n        sub.add_argument(\"--reference\", required=True, help=\"Reuse the same reference for the same logical order\")\n        sub.add_argument(\"--sku\", default=\"MVnHs-Wh-S\")\n        if name == \"plain\":\n            sub.add_argument(\"--submit-sandbox\", action=\"store_true\", help=\"Actually create one plain Sandbox order\")\n        else:\n            sub.add_argument(\"--order-id\", required=True, help=\"Manually confirmed ID of an existing plain Sandbox test\")\n    return cli\n\n\nasync def run(args) -> dict:\n    order = None\n    if args.command in {\"plain\", \"remember\"}:\n        order = PlainOrder(reference=args.reference, sku=args.sku, shipping_address=TEST_ADDRESS)\n        if args.command == \"plain\" and not args.submit_sandbox:\n            return {\"environment\": \"sandbox\", \"dry_run\": True, \"payload\": order.payload()}\n    journal = SandboxJournal(args.journal)\n    async with SandboxClient.from_env(journal) as client:\n        if args.command == \"auth\":\n            await client.authenticate()\n            return {\"environment\": \"sandbox\", \"authenticated\": True}\n        if args.command == \"plain\":\n            return {\"environment\": \"sandbox\", **await client.create_plain_order(order)}\n        if args.command == \"remember\":\n            return {\"environment\": \"sandbox\", \"source\": \"operator_confirmed\",\n                    \"reference\": order.reference, **client.remember_existing(order, args.order_id)}\n        if args.command == \"status\":\n            return {\"environment\": \"sandbox\", \"record\": journal.get(client.account, args.reference)}\n        return {\"environment\": \"sandbox\", **await client.lookup(args.order_id)}\n\n\ndef main() -> int:\n    args = parser().parse_args()\n    load_dotenv(ROOT / \".env\")\n    try:\n        result = asyncio.run(run(args))\n    except QikinkError as exc:\n        print(json.dumps({\"environment\": \"sandbox\", \"error\": str(exc), \"error_type\": type(exc).__name__}))\n        return 1\n    except (Exception, KeyboardInterrupt) as exc:\n        # Validation errors, transport URLs, and SQLite messages can expose data.\n        print(json.dumps({\"environment\": \"sandbox\", \"error_type\": type(exc).__name__,\n                          \"detail\": \"Check failed; details withheld. Inspect the journal before retrying submission.\"}))\n        return 1\n    print(json.dumps(result, indent=2))\n    return 2 if result.get(\"state\") == \"unverified\" else 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n",
  "server/tests/test_qikink.py": "\"\"\"Qikink Sandbox contract and duplicate protection; all HTTP calls are mocked.\"\"\"\nimport asyncio\nimport json\nimport os\nimport sys\nimport tempfile\nimport unittest\nfrom pathlib import Path\nfrom unittest.mock import patch\n\nimport httpx\nfrom pydantic import ValidationError\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[1]))\nfrom services.qikink import (DuplicateBlocked, OutcomeUnknown, PlainOrder, QikinkError,\n                              SandboxClient, SandboxJournal)\n\nADDRESS = {\n    \"first_name\": \"Sandbox\", \"last_name\": \"Test\", \"address1\": \"Sandbox test address\",\n    \"phone\": \"9876543210\", \"email\": \"sandbox@example.com\", \"city\": \"Coimbatore\",\n    \"zip\": \"641001\", \"province\": \"Tamil Nadu\", \"country_code\": \"IN\",\n}\n\n\ndef order(reference=\"tbw_test\", **extra):\n    return PlainOrder(reference=reference, sku=\"MVnHs-Wh-S\", shipping_address=ADDRESS, **extra)\n\n\nclass QikinkTests(unittest.IsolatedAsyncioTestCase):\n    def setUp(self):\n        self.tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(self.tmp.cleanup)\n        self.path = Path(self.tmp.name) / \"sandbox.db\"\n        self.journal = SandboxJournal(self.path)\n        self.calls = []\n        env = patch.dict(os.environ, {\"QIKINK_ENV\": \"sandbox\", \"QIKINK_BASE_URL\": \"https://api.qikink.com\"})\n        env.start()\n        self.addCleanup(env.stop)\n\n    def client(self, handler=None):\n        async def respond(request):\n            self.assertEqual(request.url.scheme, \"https\")\n            self.assertEqual(request.url.host, \"sandbox.qikink.com\")\n            self.calls.append(request.url.path)\n            if handler:\n                reply = handler(request)\n                return await reply if asyncio.iscoroutine(reply) else reply\n            if request.url.path == \"/api/token\":\n                self.assertIn(b\"ClientId=test-client\", request.content)\n                self.assertIn(b\"client_secret=test-secret\", request.content)\n                return httpx.Response(200, json={\"Accesstoken\": \"private-token\", \"expires_in\": 3600})\n            self.assertEqual(request.url.path, \"/api/order/create\")\n            payload = json.loads(request.content)\n            self.assertEqual(request.headers[\"Accesstoken\"], \"private-token\")\n            self.assertEqual(payload[\"gateway\"], \"Prepaid\")\n            self.assertEqual(payload[\"line_items\"][0][\"print_type_id\"], \"1\")\n            self.assertNotIn(\"designs\", payload[\"line_items\"][0])\n            return httpx.Response(200, json={\"status_code\": \"200\", \"order_id\": 24616032})\n        return SandboxClient(\"test-client\", \"test-secret\", self.journal, transport=httpx.MockTransport(respond))\n\n    async def test_creation_survives_client_and_journal_restart_without_resending(self):\n        async with self.client() as client:\n            result = await client.create_plain_order(order())\n        self.assertEqual(result[\"order_id\"], \"24616032\")\n        self.assertFalse(result[\"cached\"])\n        self.journal = SandboxJournal(self.path)\n        async with self.client() as client:\n            again = await client.create_plain_order(order())\n        self.assertTrue(again[\"cached\"])\n        self.assertEqual(self.calls, [\"/api/token\", \"/api/order/create\"])\n        saved = self.path.read_bytes()\n        for secret in (b\"private-token\", b\"test-secret\", b\"sandbox@example.com\", b\"Sandbox test address\"):\n            self.assertNotIn(secret, saved)\n\n    async def test_changed_payload_cannot_reuse_reference(self):\n        async with self.client() as client:\n            await client.create_plain_order(order())\n            with self.assertRaises(DuplicateBlocked):\n                await client.create_plain_order(order(quantity=2))\n        self.assertEqual(self.calls.count(\"/api/order/create\"), 1)\n\n    async def test_timeout_is_persistently_uncertain_without_automatic_retry(self):\n        def respond(request):\n            if request.url.path == \"/api/token\":\n                return httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n            raise httpx.ReadTimeout(\"private-token test-secret\")\n        async with self.client(respond) as client:\n            with self.assertRaises(OutcomeUnknown) as caught:\n                await client.create_plain_order(order())\n            self.assertNotIn(\"private-token\", str(caught.exception))\n            self.assertEqual(self.journal.get(client.account, \"tbw_test\")[\"state\"], \"uncertain\")\n        self.journal = SandboxJournal(self.path)\n        async with self.client() as client:\n            with self.assertRaises(DuplicateBlocked):\n                await client.create_plain_order(order())\n        self.assertEqual(self.calls.count(\"/api/order/create\"), 1)\n\n    async def test_validation_rejection_stays_blocked_and_does_not_disclose_body(self):\n        def respond(request):\n            if request.url.path == \"/api/token\":\n                return httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n            return httpx.Response(400, json={\"error\": \"test-secret private-token\"})\n        async with self.client(respond) as client:\n            with self.assertRaises(QikinkError) as caught:\n                await client.create_plain_order(order())\n            self.assertNotIn(\"test-secret\", str(caught.exception))\n            self.assertEqual(self.journal.get(client.account, \"tbw_test\")[\"state\"], \"rejected\")\n            with self.assertRaises(DuplicateBlocked):\n                await client.create_plain_order(order())\n        self.assertEqual(self.calls.count(\"/api/order/create\"), 1)\n\n    async def test_ambiguous_creation_responses_are_not_retried(self):\n        for index, response in enumerate([\n            httpx.Response(500), httpx.Response(302, headers={\"Location\": \"https://api.qikink.com\"}),\n            httpx.Response(200, text=\"not json\"), httpx.Response(200, json={\"status_code\": \"200\"}),\n            httpx.Response(200, json={\"status_code\": \"400\", \"order_id\": 123}),\n            httpx.Response(200, json={\"status_code\": \"200\", \"order_id\": True}),\n        ]):\n            def respond(request):\n                return (httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n                        if request.url.path == \"/api/token\" else response)\n            async with self.client(respond) as client:\n                with self.assertRaises(OutcomeUnknown):\n                    await client.create_plain_order(order(f\"case_{index}\"))\n                with self.assertRaises(DuplicateBlocked):\n                    await client.create_plain_order(order(f\"case_{index}\"))\n        self.assertEqual(self.calls.count(\"/api/order/create\"), 6)\n\n    async def test_failure_before_submission_can_be_safely_retried(self):\n        def respond(request):\n            return httpx.Response(200, json={\"Accesstoken\": \"\", \"error\": \"test-secret\"})\n        async with self.client(respond) as client:\n            with self.assertRaises(QikinkError):\n                await client.create_plain_order(order())\n            self.assertEqual(self.journal.get(client.account, \"tbw_test\")[\"state\"], \"not_sent\")\n        async with self.client() as client:\n            self.assertEqual((await client.create_plain_order(order()))[\"state\"], \"created\")\n        self.assertEqual(self.calls.count(\"/api/order/create\"), 1)\n\n    async def test_concurrent_clients_share_atomic_reservations(self):\n        entered = asyncio.Event()\n        release = asyncio.Event()\n        async def respond(request):\n            if request.url.path == \"/api/token\":\n                return httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n            entered.set()\n            await release.wait()\n            return httpx.Response(200, json={\"status_code\": \"200\", \"order_id\": 123})\n        async with self.client(respond) as first, self.client() as second:\n            second.journal = SandboxJournal(self.path)\n            pending = asyncio.create_task(first.create_plain_order(order()))\n            await asyncio.wait_for(entered.wait(), timeout=2)\n            try:\n                with self.assertRaises(DuplicateBlocked):\n                    await second.create_plain_order(order())\n            finally:\n                release.set()\n                await pending\n        self.assertEqual(self.calls.count(\"/api/order/create\"), 1)\n\n    async def test_token_is_reused_until_expiry(self):\n        async with self.client() as client:\n            await client.create_plain_order(order(\"one\"))\n            await client.create_plain_order(order(\"two\"))\n            self.assertEqual(self.calls.count(\"/api/token\"), 1)\n            client._expires = 0\n            await client.create_plain_order(order(\"three\"))\n        self.assertEqual(self.calls.count(\"/api/token\"), 2)\n\n    async def test_manual_existing_order_blocks_submission_without_network(self):\n        async with self.client() as client:\n            client.remember_existing(order(\"tbw_9ba7265277\"), \"24616032\")\n            result = await client.create_plain_order(order(\"tbw_9ba7265277\"))\n            self.assertTrue(result[\"cached\"])\n            with self.assertRaises(DuplicateBlocked):\n                client.remember_existing(order(\"tbw_9ba7265277\"), \"999\")\n        self.assertEqual(self.calls, [])\n\n    async def test_read_failure_preserves_confirmed_creation(self):\n        async with self.client() as client:\n            client.remember_existing(order(), \"24616032\")\n            account = client.account\n        def respond(request):\n            if request.url.path == \"/api/token\":\n                return httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n            return httpx.Response(404 if request.url.path.endswith(\"list\") else 500)\n        async with self.client(respond) as client:\n            result = await client.lookup(\"24616032\")\n        self.assertEqual(result[\"state\"], \"unverified\")\n        self.assertEqual([a[\"http_status\"] for a in result[\"attempts\"]], [404, 500])\n        self.assertEqual(self.journal.get(account, \"tbw_test\")[\"state\"], \"created\")\n        self.assertNotIn(\"/api/order/create\", self.calls)\n\n    async def test_http_200_alone_does_not_confirm_order_lookup(self):\n        for body in ({\"success\": True, \"data\": []}, {\"data\": [{\"order_id\": \"999\"}]},\n                     {\"success\": False, \"data\": [{\"order_id\": \"24616032\"}]}):\n            def respond(request):\n                return (httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n                        if request.url.path == \"/api/token\" else httpx.Response(200, json=body))\n            async with self.client(respond) as client:\n                self.assertEqual((await client.lookup(\"24616032\"))[\"state\"], \"unverified\")\n\n    async def test_lookup_requires_matching_order_id(self):\n        def respond(request):\n            return (httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n                    if request.url.path == \"/api/token\" else\n                    httpx.Response(200, json={\"success\": True, \"data\": [{\"order_id\": 24616032}]}))\n        async with self.client(respond) as client:\n            self.assertEqual((await client.lookup(\"24616032\"))[\"state\"], \"found\")\n        self.assertNotIn(\"/api/order/create\", self.calls)\n\n    async def test_payload_is_snapshotted_before_authentication(self):\n        original = order()\n        async def respond(request):\n            if request.url.path == \"/api/token\":\n                original.shipping_address.city = \"Changed during authentication\"\n                return httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n            self.assertEqual(json.loads(request.content)[\"shipping_address\"][\"city\"], \"Coimbatore\")\n            return httpx.Response(200, json={\"status_code\": \"200\", \"order_id\": 1})\n        async with self.client(respond) as client:\n            await client.create_plain_order(original)\n\n    def test_live_mode_is_refused(self):\n        with patch.dict(os.environ, {\"QIKINK_ENV\": \"live\"}):\n            with self.assertRaises(QikinkError):\n                self.client()\n\n    def test_invalid_orders_fail_before_network(self):\n        for change in ({\"reference\": \"TOO-LONG-REFERENCE\"}, {\"quantity\": 0}, {\"quantity\": True},\n                       {\"quantity\": 101}, {\"price\": \"NaN\"}, {\"total_order_value\": \"-1\"}):\n            data = order().model_dump() | change\n            with self.assertRaises(ValidationError):\n                PlainOrder.model_validate(data)\n        self.assertEqual(self.calls, [])\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "server/docs/QIKINK_SANDBOX.md": "# Qikink Sandbox backend\n\nThis client implements the confirmed India plain-product test flow only. It has\nno checkout hooks, production host selector, wallet endpoint, payment capture,\nartwork upload, or automatic retry of order creation. Existing store behavior is\nunchanged. New printed products and live fulfillment need a separate integration.\n\nReference: https://documenter.getpostman.com/view/26157218/2sBYAysUHS\nThe supplied PDF documents plain products with print_type_id=1 and no designs.\nIt also warns that Get Order is unavailable in Sandbox. The observed routes\nreturned 404 (/api/order/list) and 500 (/api/order).\n\n## Configuration\n\nUse the existing server/.env (never commit credentials):\n\n```dotenv\nQIKINK_ENV=sandbox\nQIKINK_SANDBOX_CLIENT_ID=...\nQIKINK_SANDBOX_CLIENT_SECRET=...\n```\n\nQIKINK_ENV defaults to sandbox; any other value is refused. There is no live URL\nconfiguration: calls always use https://sandbox.qikink.com, with redirects off.\nThe CLI reads server/.env without replacing already exported variables. Run it\nas the same Unix user using the same persistent journal each time. On the VPS,\nthe app service runs as www-data; use that ownership for the journal if running\nscripts as root first. No service restart is needed for standalone CLI commands.\n\n## Commands (from server/)\n\n```bash\n.venv/bin/python scripts/qikink_sandbox.py auth\n.venv/bin/python scripts/qikink_sandbox.py plain --reference tbw_test001\n# Above is a dry run, without network calls or order creation.\n# Explicit submission, ONLY when a new Sandbox order is wanted:\n.venv/bin/python scripts/qikink_sandbox.py plain --reference tbw_test001 --submit-sandbox\n.venv/bin/python scripts/qikink_sandbox.py lookup 24616032\n.venv/bin/python scripts/qikink_sandbox.py status tbw_test001\n```\n\nCLI plain defaults match the successfully tested SKU MVnHs-Wh-S, quantity 1,\nvalue 1, Prepaid, no design, synthetic India address. These are test values, not\npricing or customer data. `lookup` returns exit code 2 for an unverified read;\nthis never changes a confirmed creation into a failure or creates a replacement.\nExit code 1 indicates a failed command, 0 a completed command or dry run.\n\n### Preserve the already created order (no API call)\n\nThe operator confirmed a successful response for reference tbw_9ba7265277,\norder ID 24616032. Register that exact plain test payload in the local journal:\n\n```bash\n.venv/bin/python scripts/qikink_sandbox.py remember --reference tbw_9ba7265277 --order-id 24616032\n.venv/bin/python scripts/qikink_sandbox.py status tbw_9ba7265277\n```\n\n`remember` is a local assertion by the operator, not remote verification. It\naccepts only this CLI's plain test payload (including --sku if specified), and\nrefuses to replace a pending/uncertain record or an existing different ID. Do not\nuse it for a different payload or account. It does not reserve a remote reference.\n\n## Duplicate protection and recovery\n\nThe independent SQLite file server/data/qikink_sandbox.db stores account hashes,\nreferences, payload hashes, states, IDs and timestamps. No token, secret, address,\nemail, or request/response body is stored. It does not touch store.db.\n\nAtomic SQLite reservations protect concurrent workers sharing this same file.\nAlways reuse the same reference for the same logical order and preserve the\njournal. A different payload with the same reference is refused. A created record\nreturns its saved ID without authentication or another POST.\n\n- pending: reservation exists; a crashed process may have submitted the request.\n- not_sent: authentication failed before the creation call; same payload can retry.\n- rejected: creation returned HTTP 400; no automatic retry for this reference.\n- uncertain: timeout, cancellation, redirect, HTTP error other than 400, malformed\n  response, missing/invalid ID, or ambiguous result. Submission stays blocked.\n- created: HTTP 200 + status_code=200 + a positive numeric order_id was recorded,\n  or an operator registered an already confirmed test.\n\nDo not delete the journal, switch --journal paths, generate a new reference, or\nclear an uncertain/pending row merely to retry an ambiguous submission. Reconcile\nwith Qikink/dashboard/support first. The local guard cannot cover orders created\noutside it unless registered, or independent machines with different databases.\nA database commit failure after remote success can leave pending; keep it blocked.\n\nThe access token is cached until expiry within one client instance. Qikink's token\nendpoint replaces previous tokens; avoid competing token generators in separate\nprocesses. Authentication problems are surfaced; order POSTs are never replayed.\n\n## Offline verification\n\n```bash\n# From repository root; mocked HTTP, temporary SQLite, no remote orders:\nserver/.venv/bin/python -m unittest discover -s server/tests -p 'test_qikink*.py' -v\n```\n\nLive evidence supplied by the operator, not rerun by these tests:\nauthentication HTTP 200; plain creation HTTP 200, ID 24616032;\nlookup /api/order/list HTTP 404 and /api/order HTTP 500. Printed fulfillment,\nshipping quotes, tracking, payments, and production readiness remain unverified.\n"
}
HASHES = {'server/services/qikink.py': '36b7b8907590491344c0c18228caddb0ac03a91b63eff82bd9eb6ea10f791faf', 'server/scripts/qikink_sandbox.py': '8ad8fbedbff623cd3deb0c9344fdd473a9b98fcaaee46697cdc40a1970c4102e', 'server/tests/test_qikink.py': '75e7e0199c19080e60c98f2359d356bd8f0a63dfd9f0be30eb31cd2246f556da', 'server/docs/QIKINK_SANDBOX.md': 'fac61711aa328ffe78e2776ea18ea394bf4ad686bfd53f9f5cf57d1d060c79af'}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=Path("/var/www/thebookswanderer.com"))
    args = parser.parse_args()
    root = args.root.resolve()
    if not (root / "server" / ".env").is_file():
        raise RuntimeError("Server .env not found; nothing installed")

    # Run the Sandbox tests in isolation BEFORE replacing any target files.
    with tempfile.TemporaryDirectory(prefix="qikink-verify-") as staging:
        stage = Path(staging)
        for name, content in FILES.items():
            if hashlib.sha256(content.encode()).hexdigest() != HASHES[name]:
                raise RuntimeError("Package checksum mismatch")
            target = stage / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(content)
        subprocess.run([sys.executable, "-m", "unittest", "discover", "-s",
                        str(stage / "server/tests"), "-p", "test_qikink.py", "-v"],
                       cwd=stage, check=True)

    # Back up only previous versions of these four package files when different.
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
    backup = root / "server/data/qikink-install-backups" / stamp
    for name, content in FILES.items():
        target = root / name
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.exists():
            if target.read_text() == content:
                continue
            saved = backup / name
            saved.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, saved)
        fd, temp_name = tempfile.mkstemp(prefix=".qikink-install-", dir=target.parent)
        try:
            with os.fdopen(fd, "w") as stream:
                stream.write(content)
                stream.flush()
                os.fsync(stream.fileno())
                os.fchmod(stream.fileno(), 0o644)
            os.replace(temp_name, target)
        finally:
            if os.path.exists(temp_name):
                os.unlink(temp_name)

    # Local operator-confirmed record only: never call authenticate/create here.
    cli = [sys.executable, str(root / "server/scripts/qikink_sandbox.py")]
    subprocess.run(cli + ["remember", "--reference", "tbw_9ba7265277",
                         "--order-id", "24616032"], check=True)
    journal = root / "server/data/qikink_sandbox.db"
    os.chmod(journal, 0o600)
    if os.geteuid() == 0:
        user = pwd.getpwnam("www-data")
        os.chown(journal, user.pw_uid, user.pw_gid)
    subprocess.run(cli + ["status", "tbw_9ba7265277"], check=True)
    print("Instalación completada. Pedido 24616032 registrado localmente.")
    print("Sin llamadas a Qikink, pedidos nuevos, cambios en .env ni reinicio de la tienda.")
    if backup.exists():
        print("Copia de los archivos anteriores:", backup)


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print("Instalación incompleta:", type(exc).__name__)
        print("No se enviaron pedidos. No borres el registro; revisa el estado antes de continuar.")
        sys.exit(1)
